frappe.ui.form.on("Weekly Regional Report", {
    refresh: function(frm) {
        if (!frm.doc.weekly_report || !frm.doc.last_generated_on || frm.doc.last_data_update > frm.doc.last_generated_on) {
            frm.add_custom_button("Create Report", () => {
                frappe.call({
                    method: "nacoc.my_scripts.weekly_regional_reports.generate_weekly_report",
                    args: { docname: frm.doc.name },
                    freeze: true,
                    freeze_message: __("Generating Report..."),
                    callback: function(r) {
                        if (r.message) {
                            frm.set_value("weekly_report", r.message);
                            frm.set_value("last_generated_on", frappe.datetime.now_datetime());
                            frm.save();
                            frappe.msgprint("Weekly report generated successfully");
                            frm.refresh();
                        }
                    }
                });
            }).addClass("btn-primary");
        }
    },
    week_start_date: function(frm) {
        if (frm.doc.week_start_date) {
            let start = frappe.datetime.str_to_obj(frm.doc.week_start_date);

            // Calculate ISO week number
            let date = new Date(start.getTime());
            date.setHours(0,0,0,0);

            date.setDate(date.getDate() + 3 - ((date.getDay() + 6) % 7));
            let week1 = new Date(date.getFullYear(), 0, 4);
            let weekNumber = 1 + Math.round(
                ((date.getTime() - week1.getTime()) / 86400000 - 3 + ((week1.getDay() + 6) % 7)) / 7
            );

            frm.set_value("week_number", weekNumber);

            let monthNames = [
                "January", "February", "March", "April", "May", "June",
                "July", "August", "September", "October", "November", "December"
            ];
            frm.set_value("month", monthNames[start.getMonth()]);

            frm.set_value("year", start.getFullYear());

            // Optional: auto-fill week_end_date as +6 days
            let end = frappe.datetime.add_days(frm.doc.week_start_date, 6);
            frm.set_value("week_end_date", end);
        }
    }
});

async function fetchPermittedRegions() {
    try {
        const response = await frappe.call({
            method: "nacoc.my_scripts.custom.get_permitted_regions"
        });
        return response.message || [];
    } catch (error) {
        console.error("Error fetching permitted regions:", error);
        return [];
    }
}

async function applyPermittedRegionFilter(listview) {
    const permittedRegions = await fetchPermittedRegions();

    // Check if permittedRegions array is empty
    if (permittedRegions.length > 0) {
        frappe.route_options = {
            "region": ["in", permittedRegions]
        };
    } else {
        // If permittedRegions array is empty, clear the filter
        frappe.route_options = {};
    }
}

