frappe.ui.form.on('Training', {
	start_time: function(frm) {
        frm.set_value('start_time_set', 1);
    },
    end_time: function(frm) {
        frm.set_value('end_time_set', 1);
    },
    validate: function(frm) {
        const start_date = frm.doc.start_date;
        const end_date = frm.doc.end_date;
        const start_time = frm.doc.start_time;
        const end_time = frm.doc.end_time;

        // 1. Check date range
        if (start_date && end_date && start_date > end_date) {
            frappe.msgprint(__('Start Date must be less than or equal to End Date.'));
            frappe.validated = false;
            return;
        }

        // 2. Check time range if both times are provided
        if (start_time && end_time) {
            if (start_time >= end_time) {
                frappe.msgprint(__('Start Time must be earlier than End Time.'));
                frappe.validated = false;
            }
        }
    }
});

