                    if (bookDetails) {
                        frm.set_value('book_title', bookDetails.book_title);
                        frm.set_value('book_type', bookDetails.book_type);
                        frm.set_value('category', bookDetails.category);
                        frm.set_value('year_published', bookDetails.year_published);
