frappe.ui.form.on('Clearance Permit', {
    onload: function(frm) {
        if (frm.doc.quantity != null) {
            let formatted = Number(frm.doc.quantity).toLocaleString();
            frm.fields_dict.quantity.$wrapper.find('input').val(formatted);
        }
    },
    before_save: function(frm) {
        if (typeof frm.doc.quantity === 'string') {
            frm.set_value('quantity', parseInt(frm.doc.quantity.replace(/,/g, '')));
        }
    },
    quantity: function(frm) {
        if (frm.doc.quantity != null) {
            let formatted = Number(frm.doc.quantity).toLocaleString();
            frm.fields_dict.quantity.$wrapper.find('input').val(formatted);
        }
    },
    importing_company: function (frm) {
        if (frm.doc.importing_company) {
            frappe.db.get_doc('Precursor Company', frm.doc.importing_company).then(company_doc => {
                frm.set_value('importing_company_address', company_doc.company_address);
            });
        } else {
            frm.set_value('importing_company_address', '');
        }
    },
    precursor_chemical: function(frm) {
        frm.set_value('permit_no', '');
        if (frm.doc.precursor_chemical) {
            frappe.db.get_value('Substance', frm.doc.precursor_chemical, 'substance_code')
                .then(r => {
                    if (r.message) {
                        frm.set_value('precursor_chemical_code', r.message.substance_code);
                        frm.trigger('generate_permit_no');
                    }
                });
        } else {
            frm.set_value('precursor_chemical_code', '');
        }
    },

    generate_permit_no: function(frm) {
        if (!frm.doc.precursor_chemical_code) {
            frappe.msgprint(__('Precursor Chemical Code is required to generate Permit No'));
            return;
        }

        frappe.call({
            method: 'nacoc.my_scripts.clearance_permit.get_next_clearance_permit_preview',
            args: {
                precursor_chemical_code: frm.doc.precursor_chemical_code
            },
            callback: function(r) {
                if (r.message) {
                    frm.set_value('permit_no', r.message);
                }
            }
        });
    }
});

frappe.ui.form.on('Vehicle Maintenance Allowance', {
	refresh: function(frm) {
	    frm.set_df_property('employee_name', 'read_only', 1);
	},
	onload: function(frm) {
        if (frm.is_new()) {
            frappe.call({
                type: "GET",
                url: "/api/method/get_logged_in_employee_info",
                error: function(xhr) {
                    // Handle HTTP errors
                    let message = "Failed to fetch employee info.";
                    try {
                        let response = JSON.parse(xhr.responseText);
                        if (response && response.message && response.message.error) {
                            message = response.message.error;
                        }
                    } catch (e) {
                        // JSON parse failed, keep default message
                    }
                    frappe.msgprint({title: __("Error"), indicator: "red", message: message});
                },
                callback: function(response) {
                    if (response.message) {
                        if (response.message.error) {
                            // Show error message if server sent error
                            frappe.msgprint({title: __("Error"), indicator: "orange", message: response.message.error});
                        } else {
                            // Set form values and make employee_name readonly
                            frm.set_value("employee_name", response.message.employee_name);
                            frm.set_df_property('employee_name', 'read_only', 1);
                            frm.set_value("phone_number", response.message.cell_number);
                        }
                    }
                }
            });
        }
        if (frm.is_new() && !frm.doc.application_year) {
            const currentYear = new Date().getFullYear();
            frm.set_value('application_year', currentYear);
        }

    }
})

frappe.ui.form.on('Vehicle Maintenance Allowance', {
	refresh(frm) {
        frm.disable_save(); // hides default save button

        frm.add_custom_button('Save', async function() {
            try {
                await handle_validated_save(frm);
            } catch (err) {
                frappe.msgprint(err.message);
            }
        }).removeClass("btn-default").addClass("btn-primary");

        // Set up custom file inputs
        frm.selected_files = {};

        const fields = [
            { html_field: 'upload_form_a', data_field: 'form_a_file_url', label: 'Upload Form A or C' },
            { html_field: 'upload_road_worthiness', data_field: 'road_worthiness_file_url', label: 'Upload Road Worthiness' },
            { html_field: 'upload_drivers_licence', data_field: 'drivers_licence_file_url', label: 'Upload Driver\'s Licence' },
            { html_field: 'upload_vehicle_insurance', data_field: 'vehicle_insurance_file_url', label: 'Upload Vehicle Insurance' }
        ];

        fields.forEach(f => {
            frm.fields_dict[f.html_field].$wrapper.html(`
                <label class="control-label reqd">${f.label}</label><br/>
                <input type="file" id="${f.html_field}_file" style="display:inline-block; margin-right: 10px; margin-bottom: 20px;font-size: var(--text-sm);" />
                <button type="button" class="btn btn-xs btn-danger" id="clear_${f.html_field}" style="display: none;">
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" 
                        viewBox="0 0 24 28" fill="none" stroke="#ffffff" 
                        stroke-width="5" stroke-linecap="round" stroke-linejoin="round">
                        <line x1="18" y1="6" x2="6" y2="18"></line>
                        <line x1="6" y1="6" x2="18" y2="18"></line>
                    </svg>
                </button>
                <div id="status_${f.html_field}" style="margin-top: 5px; font-size: 90%; color: #555;"></div>
            `);

            setTimeout(() => {
                const input = document.getElementById(`${f.html_field}_file`);
                const clearBtn = document.getElementById(`clear_${f.html_field}`);
                const status = document.getElementById(`status_${f.html_field}`);

                // Initially hide clear button
                clearBtn.style.display = "none";
                status.innerText = "";

                // Handle file selection
                input.addEventListener('change', (event) => {
                    const file = event.target.files[0];
                    if (file) {
                        const isImage = file.type.startsWith("image/");
                        const isPDF = file.type === "application/pdf";
                        const maxSize = 2 * 1024 * 1024; // 2MB

                        if (!(isImage || isPDF)) {
                            frappe.msgprint("Only PDF or image files are allowed.");
                            input.value = "";
                            delete frm.selected_files[f.data_field];
                            status.innerText = "";
                            clearBtn.style.display = "none";
                            return;
                        }

                        if (file.size > maxSize) {
                            frappe.msgprint("File size must be less than 2MB.");
                            input.value = "";
                            delete frm.selected_files[f.data_field];
                            status.innerText = "";
                            clearBtn.style.display = "none";
                            return;
                        }

                        frm.selected_files[f.data_field] = file;
                        clearBtn.style.display = "inline-block";
                    } else {
                        delete frm.selected_files[f.data_field];
                        status.innerText = '';
                        clearBtn.style.display = "none";
                    }
                });

                // Handle clear button click
                clearBtn.addEventListener('click', () => {
                    input.value = ""; // Reset file input
                    delete frm.selected_files[f.data_field];
                    status.innerText = "";
                    clearBtn.style.display = "none"; // ✅ Hide Clear button again
                });
            }, 100);
        });
    }
});

async function handle_validated_save(frm) {
    // Step 1: Validate standard required fields
    const missing_mandatory = frm.meta.fields
        .filter(df => df.reqd && !frm.doc[df.fieldname])
        .map(df => df.label);

    if (missing_mandatory.length) {
        throw new Error(`Please fill in all mandatory fields: <br>${missing_mandatory.join(' <br>')}`);
    }

    // Step 2: Validate required file fields
    const requiredFiles = [
        'form_a_file_url',
        'road_worthiness_file_url',
        'drivers_licence_file_url',
        'vehicle_insurance_file_url'
    ];

    for (let field of requiredFiles) {
        if (!frm.doc[field] && !frm.selected_files?.[field]) {
            throw new Error(`Please select a file for ${frappe.meta.get_label(frm.doctype, field, frm.doc.name)}`);
        }
    }

    // Step 3: Save the form first to get a valid docname
    if (frm.doc.__islocal) {
        await frm.save(); // generates real name
    }

    // Step 4: Upload files (now we have real docname)
    const uploaded_files = [];

    for (let [field, file] of Object.entries(frm.selected_files || {})) {
        // 🧹 Step 1: Delete existing file if any
        const existing_url = frm.doc[field];
        if (existing_url) {
            const existing_file = await frappe.db.get_value('File', { file_url: existing_url }, 'name');
            if (existing_file?.name) {
                // ✅ Correct and reliable way to delete the file + remove from sidebar
                await frappe.call({
                    method: "frappe.desk.form.attachments.remove_file",
                    args: {
                        fid: existing_file.name,
                        dt: frm.doctype,
                        dn: frm.docname
                    }
                });
            }
        }

        // 📤 Step 2: Upload new file
        const formData = new FormData();
        formData.append('file', file);
        formData.append('is_private', 1);
        formData.append('attached_to_doctype', frm.doctype);
        formData.append('attached_to_name', frm.docname);

        const response = await fetch('/api/method/upload_file', {
            method: 'POST',
            body: formData,
            headers: {
                'X-Frappe-CSRF-Token': frappe.csrf_token
            }
        });

        const result = await response.json();

        if (result.message?.file_url) {
            // ✅ Set new file URL
            await frm.set_value(field, result.message.file_url);

            // ✅ Redundant: forcibly link File to doc
            await frappe.call('frappe.client.set_value', {
                doctype: 'File',
                name: result.message.name,
                fieldname: {
                    attached_to_doctype: frm.doctype,
                    attached_to_name: frm.docname
                }
            });
        } else {
            throw new Error(`Upload failed for ${field}`);
        }
    }

    // Step 5: Save again to commit file_url fields
    await frm.save();

    // Step 6: Refresh the sidebar
    frm.attachments.refresh();
}

